const brand=document.querySelector('.brand');
if(brand){
  brand.innerHTML='<div class="cn-wordmark">'+(brush?brush('brand-brush-sidebar'):'辰南')+'</div><div class="brand-copy"><b>辰南撰写</b><small>让人物拥有灵魂</small></div>';
}
