/* ===== 2026-09-30 · Contrast protection v6 ===== */
(function(){'use strict';const st=document.createElement('style');st.id='chennanContrastProtectionV6';st.textContent="\n/* 旧业务模块中存在写死 #fff/#fafbfe 的浅色表面。夜间主题必须把这些表面的文字重新锚定到深色。 */\nhtml[data-theme=\"night\"] .people-data-table,\nhtml[data-theme=\"night\"] .people-data-table tbody,\nhtml[data-theme=\"night\"] .people-data-table tbody tr,\nhtml[data-theme=\"night\"] .offer-stat,\nhtml[data-theme=\"night\"] .offer-row.active,\nhtml[data-theme=\"night\"] .candidate-card,\nhtml[data-theme=\"night\"] .detail-line,\nhtml[data-theme=\"night\"] .mini-table,\nhtml[data-theme=\"night\"] .mini-table tbody,\nhtml[data-theme=\"night\"] .mini-table tbody tr,\nhtml[data-theme=\"night\"] .rich-editor,\nhtml[data-theme=\"night\"] .word-toolbar,\nhtml[data-theme=\"night\"] .daily-tab,\nhtml[data-theme=\"night\"] .daily-pick input,\nhtml[data-theme=\"night\"] .memory-person-card,\nhtml[data-theme=\"night\"] .memory-row{\n  color:#1f2937!important;\n}\n\nhtml[data-theme=\"night\"] .people-data-table{background:#f7f9fc!important}\nhtml[data-theme=\"night\"] .people-data-table th{\n  background:#e9eef5!important;color:#465568!important;\n  border-bottom-color:#cbd5e1!important;font-weight:800!important;\n}\nhtml[data-theme=\"night\"] .people-data-table td{\n  color:#1f2937!important;background:#f9fbfd!important;\n  border-bottom-color:#d4dce7!important;font-weight:600!important;\n}\nhtml[data-theme=\"night\"] .people-data-table .namecell{\n  color:#111827!important;font-weight:850!important;\n}\nhtml[data-theme=\"night\"] .people-data-table tbody tr:hover td{background:#eaf2ff!important}\nhtml[data-theme=\"night\"] .people-data-table .link-btn{color:#1d63b8!important}\nhtml[data-theme=\"night\"] .people-data-table .link-btn.danger{color:#b42318!important}\n\nhtml[data-theme=\"night\"] .offer-row.active{\n  background:#f7f9fc!important;border-color:#d6b467!important;\n}\nhtml[data-theme=\"night\"] .offer-row.active b{color:#111827!important;font-weight:850!important}\nhtml[data-theme=\"night\"] .offer-row.active .muted{color:#59697d!important}\nhtml[data-theme=\"night\"] .offer-stat{\n  background:#f7f9fc!important;border-color:#d8e0ea!important;\n}\nhtml[data-theme=\"night\"] .offer-stat span{color:#667085!important;font-weight:650!important}\nhtml[data-theme=\"night\"] .offer-stat b{color:#111827!important;font-weight:850!important}\nhtml[data-theme=\"night\"] .candidate-card{background:#fff!important;color:#1f2937!important}\nhtml[data-theme=\"night\"] .candidate-card .meta{color:#5b6675!important}\n\nhtml[data-theme=\"night\"] .detail-line{background:#f8fafc!important;color:#111827!important}\nhtml[data-theme=\"night\"] .detail-line span{color:#667085!important}\nhtml[data-theme=\"night\"] .detail-line b{color:#111827!important}\nhtml[data-theme=\"night\"] .mini-table{background:#fff!important;color:#1f2937!important}\nhtml[data-theme=\"night\"] .mini-table th{color:#475467!important;background:#eef2f6!important}\nhtml[data-theme=\"night\"] .mini-table td{color:#1f2937!important;background:#fff!important}\n\nhtml[data-theme=\"night\"] .rich-editor{background:#fff!important;color:#182230!important}\nhtml[data-theme=\"night\"] .rich-editor *{color:inherit}\nhtml[data-theme=\"night\"] .word-toolbar{background:#f7f9fc!important;color:#344054!important}\nhtml[data-theme=\"night\"] .word-toolbar button{background:#fff!important;color:#344054!important;border-color:#d0d5dd!important}\nhtml[data-theme=\"night\"] .daily-tab{background:#fff!important;color:#475467!important}\nhtml[data-theme=\"night\"] .daily-tab.active{background:#fff4d6!important;color:#6e4c11!important;border-color:#d6a84a!important}\nhtml[data-theme=\"night\"] .daily-pick input{background:#fff!important;color:#344054!important}\nhtml[data-theme=\"night\"] .memory-person-card,\nhtml[data-theme=\"night\"] .memory-row{background:#f8fafc!important;color:#1f2937!important}\nhtml[data-theme=\"night\"] .memory-person-card small,\nhtml[data-theme=\"night\"] .memory-person-card p,\nhtml[data-theme=\"night\"] .memory-row small,\nhtml[data-theme=\"night\"] .memory-row p{color:#667085!important}\n\n/* 手机端增强正文可读性，避免浅灰细字。 */\n@media(max-width:760px){\n  .people-data-table th{font-size:12px!important}\n  .people-data-table td{font-size:13px!important;line-height:1.45!important}\n  .people-data-table .namecell{font-size:14px!important}\n  #tradeRecommend .offer-row b{font-size:15px!important}\n  #tradeRecommend .offer-row .muted{font-size:12px!important;line-height:1.65!important}\n  #tradeRecommend .offer-stat span{font-size:12px!important}\n  #tradeRecommend .offer-stat b{font-size:16px!important;line-height:1.35!important}\n  #tradeRecommend .offer-grid{gap:8px!important}\n  #tradeRecommend .offer-stat{min-height:92px!important;padding:12px!important}\n  #people .people-table-wrap{-webkit-overflow-scrolling:touch}\n}\n\n/* 浅色主题同样确保核心业务表面达到稳定对比度。 */\nhtml[data-theme=\"warm\"] .people-data-table,\nhtml[data-theme=\"blue\"] .people-data-table{color:#1f2937!important}\nhtml[data-theme=\"warm\"] .people-data-table td,\nhtml[data-theme=\"blue\"] .people-data-table td{color:#293444!important}\nhtml[data-theme=\"warm\"] .offer-stat b,\nhtml[data-theme=\"blue\"] .offer-stat b,\nhtml[data-theme=\"warm\"] .offer-row.active b,\nhtml[data-theme=\"blue\"] .offer-row.active b{color:#202939!important}\n";document.head.appendChild(st);})();
